selector_to_html = {"a[href=\"#debug-mode\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Debug Mode<a class=\"headerlink\" href=\"#debug-mode\" title=\"Link to this heading\">\u00b6</a></h3><p>Enable debug output for troubleshooting:</p>", "a[href=\"#data-analysis\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Data Analysis<a class=\"headerlink\" href=\"#data-analysis\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#prerequisites\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Prerequisites<a class=\"headerlink\" href=\"#prerequisites\" title=\"Link to this heading\">\u00b6</a></h2><h3>System Requirements<a class=\"headerlink\" href=\"#system-requirements\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#getting-started\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Getting Started<a class=\"headerlink\" href=\"#getting-started\" title=\"Link to this heading\">\u00b6</a></h1><p>Welcome to haive-mcp! Get up and running with 1900+ MCP servers in minutes.</p>", "a[href=\"#community\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Community<a class=\"headerlink\" href=\"#community\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#resources\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Resources<a class=\"headerlink\" href=\"#resources\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#common-issues\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Common Issues<a class=\"headerlink\" href=\"#common-issues\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#web-research\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Web Research<a class=\"headerlink\" href=\"#web-research\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#file-management\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">File Management<a class=\"headerlink\" href=\"#file-management\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#quick-install\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Quick Install<a class=\"headerlink\" href=\"#quick-install\" title=\"Link to this heading\">\u00b6</a></h2><p>Install haive-mcp with a single command:</p>", "a[href=\"#key-features\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Key Features<a class=\"headerlink\" href=\"#key-features\" title=\"Link to this heading\">\u00b6</a></h2><h3>Zero Configuration<a class=\"headerlink\" href=\"#zero-configuration\" title=\"Link to this heading\">\u00b6</a></h3><p>Haive-mcp works out of the box:</p>", "a[href=\"#system-requirements\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">System Requirements<a class=\"headerlink\" href=\"#system-requirements\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#verification\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Verification<a class=\"headerlink\" href=\"#verification\" title=\"Link to this heading\">\u00b6</a></h2><p>Verify your installation:</p>", "a[href=\"#dynamic-discovery\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Dynamic Discovery<a class=\"headerlink\" href=\"#dynamic-discovery\" title=\"Link to this heading\">\u00b6</a></h3><p>The agent analyzes your task and automatically finds the right tools:</p>", "a[href=\"#common-use-cases\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Common Use Cases<a class=\"headerlink\" href=\"#common-use-cases\" title=\"Link to this heading\">\u00b6</a></h2><h3>File Management<a class=\"headerlink\" href=\"#file-management\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#your-first-agent\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Your First Agent<a class=\"headerlink\" href=\"#your-first-agent\" title=\"Link to this heading\">\u00b6</a></h2><p>Create an MCP-enabled agent in just a few lines:</p>", "a[href=\"#getting-help\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Getting Help<a class=\"headerlink\" href=\"#getting-help\" title=\"Link to this heading\">\u00b6</a></h2><h3>Resources<a class=\"headerlink\" href=\"#resources\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#rich-ecosystem\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Rich Ecosystem<a class=\"headerlink\" href=\"#rich-ecosystem\" title=\"Link to this heading\">\u00b6</a></h3><p>Access to 1900+ MCP servers across categories:</p>", "a[href=\"#next-steps\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Next Steps<a class=\"headerlink\" href=\"#next-steps\" title=\"Link to this heading\">\u00b6</a></h2><p>Now that you\u2019re up and running:</p>", "a[href=\"#understanding-categories\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Understanding Categories<a class=\"headerlink\" href=\"#understanding-categories\" title=\"Link to this heading\">\u00b6</a></h2><p>MCP servers are organized into logical categories:</p>", "a[href=\"index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Haive MCP Documentation<a class=\"headerlink\" href=\"#haive-mcp-documentation\" title=\"Link to this heading\">\u00b6</a></h1><h2>Welcome to Haive MCP<a class=\"headerlink\" href=\"#welcome-to-haive-mcp\" title=\"Link to this heading\">\u00b6</a></h2><p>Haive MCP (Model Context Protocol) revolutionizes how AI agents acquire capabilities by enabling <strong>dynamic, runtime integration</strong> of tools, resources, and prompts from a vast ecosystem of <strong>1900+ MCP servers from top GitHub repositories</strong>.</p><p>\ud83d\ude80 <strong>The Game Changer</strong>: Your agents can now <strong>automatically discover and integrate</strong> the exact tools they need, when they need them, without any predefined configuration!</p>", "a[href=\"examples.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Examples<a class=\"headerlink\" href=\"#examples\" title=\"Link to this heading\">\u00b6</a></h1><p>Comprehensive examples demonstrating haive-mcp capabilities with 1900+ MCP servers.</p>", "a[href=\"#troubleshooting\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Troubleshooting<a class=\"headerlink\" href=\"#troubleshooting\" title=\"Link to this heading\">\u00b6</a></h2><h3>Common Issues<a class=\"headerlink\" href=\"#common-issues\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#optional-components\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Optional Components<a class=\"headerlink\" href=\"#optional-components\" title=\"Link to this heading\">\u00b6</a></h3><p>These enhance functionality but aren\u2019t required:</p>", "a[href=\"tutorials.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Tutorials<a class=\"headerlink\" href=\"#tutorials\" title=\"Link to this heading\">\u00b6</a></h1><p>Welcome to the haive-mcp tutorials! These hands-on guides will walk you through using the Model Context Protocol (MCP) with Haive\u2019s 1900+ available servers.</p>", "a[href=\"guides.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Guides<a class=\"headerlink\" href=\"#guides\" title=\"Link to this heading\">\u00b6</a></h1><p>In-depth guides for working with haive-mcp and its 1900+ available MCP servers.</p>", "a[href=\"#zero-configuration\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Zero Configuration<a class=\"headerlink\" href=\"#zero-configuration\" title=\"Link to this heading\">\u00b6</a></h3><p>Haive-mcp works out of the box:</p>"}
skip_classes = ["headerlink", "sd-stretched-link", "reference-external"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(`div.content ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }
            link.classList.add('has-tooltip');
            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: true, theme: 'light-border', delay: [200, 100], duration: [200, 100],
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
